      "Step1": "ಅಧಿಕೃತ ಸರ್ಕಾರಿ ಪೋರ್ಟಲ್ ಅಥವಾ ಹತ್ತಿರದ ಸಾಮಾನ್ಯ ಸೇವಾ ಕೇಂದ್ರಕ್ಕೆ (CSC) ಭೇಟಿ ನೀಡಿ।",
      "Step2": "ಯೋಜನೆಗಳ ಪಟ್ಟಿಯಿಂದ ಯೋಜನೆಯನ್ನು ಹುಡುಕಿ ಮತ್ತು ಆಯ್ಕೆಮಾಡಿ।",
      "Step3": "ನಿಮ್ಮ ಆಧಾರ್ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ ಮತ್ತು OTP ಬಳಸಿ ಗುರುತನ್ನು ಪರಿಶೀಲಿಸಿ।",
      "Step4": "ನಿಖರವಾದ ವೈಯಕ್ತಿಕ ಮತ್ತು ಕುಟುಂಬ ವಿವರಗಳೊಂದಿಗೆ ಅರ್ಜಿ ನಮೂನೆಯನ್ನು ಭರ್ತಿ ಮಾಡಿ।",
      "Step5": "ಎಲ್ಲಾ ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು (ಆಧಾರ್, ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ವಿಳಾಸದ ಪುರಾವೆ ಇತ್ಯಾದಿ) ಅಪ್‌ಲೋಡ್ ಮಾಡಿ।",
      "Step6": "ಫಾರ್ಮ್ ಅನ್ನು ಸಲ್ಲಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಅರ್ಜಿ ಉಲ್ಲೇಖ ಸಂಖ್ಯೆಯನ್ನು ಗುರುತು ಮಾಡಿಕೊಳ್ಳಿ।",
      "Step7": "ಅಧಿಕೃತ ಪೋರ್ಟಲ್ ಅಥವಾ ಉಮಂಗ್ ಆಪ್‌ನಲ್ಲಿ ಅಪ್ಲಿಕೇಶನ್ ಐಡಿ ಅಥವಾ ಆಧಾರ್ ಬಳಸಿ ಅರ್ಜಿ ಸ್ಥಿತಿಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ।",
